input.command:
cd /tmp/tigccchain_wipP/N03_csv && cat > /tmp/fix.js <<'EOF'
const fs = require("fs");
const p = process.argv[2];
let s = fs.readFileSync(p, "utf8");
s = s.replace(`function parseLine(line) {
  return line.split(",");
}`, `function parseLine(line) {
  const cells = [];
  let cur = "";
  let inQuotes = false;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (inQuotes) {
      if (c === '"') {
        if (line[i + 1] === '"') {
          cur += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        cur += c;
      }
    } else if (c === '"') {
      inQuotes = true;
    } else if (c === ",") {
      cells.push(cur);
      cur = "";
    } else {
      cur += c;
    }
  }
  cells.push(cur);
  return cells;
}`);
fs.writeFileSync(p, s);
EOF
node /tmp/fix.js broken.js && node test.js | tail -3; echo exit=$?; node test.js | grep 'row 245'

